export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed;
  const g = inputs.gravity;
  const m = inputs.mass;
  const tTop = u / g;
  const yTop = (u * u) / (2 * g);
  const tMax = 2 * tTop;
  const t = Math.max(0, Math.min(time, tMax));
  const v = u - g * t;
  const y = Math.max(0, u * t - 0.5 * g * t * t);
  const a = -g;
  const force = m * g;
  let motionState = 'At the top';
  if (t === 0) {
    motionState = 'Ready to toss';
  } else if (Math.abs(t - tTop) < 0.02) {
    motionState = 'At the top';
  } else if (t < tTop) {
    motionState = 'Rising';
  } else if (t < tMax) {
    motionState = 'Falling';
  } else {
    motionState = 'Back at launch height';
  }
  const objects = [];
  const leftLane = sdk.panel({
    id: 'lane.motion',
    x: 10,
    y: 10,
    w: 305,
    h: 400,
    title: 'The motion',
    state: motionState
  });
  objects.push(...leftLane);
  const rightLane = sdk.panel({
    id: 'lane.graph',
    x: 325,
    y: 10,
    w: 305,
    h: 400,
    title: 'Velocity over time',
    state: `a = -${g.toFixed(1)} m/s²`
  });
  objects.push(...rightLane);
  const rulerAxis = sdk.axis('axis.height', {
    x: 75,
    y: 350,
    length: 290,
    orientation: 'y',
    min: 0,
    max: 2.2,
    ticks: [0, 0.5, 1.0, 1.5, 2.0],
    label: 'Height (m)',
    unit: 'm'
  });
  objects.push(rulerAxis);
  const ballPixelY = 350 - (y / 2.2) * 290;
  const ballPixelX = 140;
  objects.push(sdk.circle('ball.toss', ballPixelX, ballPixelY, 28));
  const vScale = 20;
  const vVec = sdk.vector('vec.v', {
    x: ballPixelX,
    y: ballPixelY
  }, {
    value: v,
    direction: 'up',
    scale: vScale,
    label: 'v'
  });
  objects.push(...vVec);
  const aScale = 5;
  const aVec = sdk.vector('vec.a', {
    x: ballPixelX + 30,
    y: ballPixelY
  }, {
    value: a,
    direction: 'up',
    scale: aScale,
    label: 'a'
  });
  objects.push(...aVec);
  const calloutLines = [
    `v = ${v >= 0 ? '+' : ''}${v.toFixed(2)} m/s`,
    `a = ${a.toFixed(2)} m/s²`,
    `Fg = ${force.toFixed(1)} N`
  ];
  objects.push(...sdk.callout(ballPixelX + 65, ballPixelY - 20, calloutLines, {
    id: 'callout.toss'
  }));
  const numPoints = 21;
  const points = [];
  for (let i = 0; i < numPoints; i++) {
    const ptTime = (tMax * i) / (numPoints - 1);
    const ptV = u - g * ptTime;
    points.push({
      x: ptTime,
      y: ptV
    });
  }
  const vtPlot = sdk.plot('plot.vt', {
    x: 340,
    y: 50,
    w: 275,
    h: 330,
    axes: {
      x: {
        label: 'Time',
        min: 0,
        max: 1.8,
        unit: 's'
      },
      y: {
        label: 'Velocity',
        min: -5.5,
        max: 5.5,
        unit: 'm/s'
      }
    },
    series: [
      {
        label: 'v(t)',
        kind: 'line',
        points: points
      }
    ]
  });
  objects.push(vtPlot);
  const quantities = {
    launchSpeed: u,
    gravity: g,
    mass: m,
    apexTime: tTop,
    apexHeight: yTop,
    height: y,
    velocity: v,
    acceleration: a,
    force: force
  };
  const readouts = [
    {
      id: 'velocity',
      value: v
    },
    {
      id: 'acceleration',
      value: a
    },
    {
      id: 'force',
      value: force
    },
    {
      id: 'motionState',
      value: motionState
    }
  ];
  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts
    },
    quantities
  };
}
